namespace SentinelRemoteAssist;

/// <summary>
/// Regenerated by new-support-session.sh before every build — bakes that session's Hop-1
/// tunnel key + the bastion's pinned host key directly into the binary, so the finished .exe is
/// the ONLY file that needs to go to the customer (no separate session.dat companion file).
/// This file (SessionEmbedded.cs, gitignored — this .template copy is the tracked placeholder)
/// holds a live private key once generated. NEVER commit the real generated copy.
/// </summary>
internal static class SessionEmbedded
{
    /// <summary>Customer/session label from new-support-session.sh (safe slug).</summary>
    public const string SessionLabel = "";
    /// <summary>UTC ISO-8601 when this session build was minted (for the customer audit log).</summary>
    public const string SessionCreatedUtc = "";
    public const string BastionHost = "";
    public const int BastionPort = 0;
    public const int ForwardPort = 0;
    public const string KnownHostsLine = "";
    public const string PrivateKeyPem = "";

    public static bool IsConfigured => !string.IsNullOrEmpty(PrivateKeyPem);
}
